def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import defaultdict
    pts = defaultdict(list)
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                pts[grid[r][c]].append((r, c))
    # The singleton is the hub; extend each multi-cell diagonal/linear arm
    # outward from its endpoint farthest from the hub.
    hubs = [p[0] for p in pts.values() if len(p) == 1]
    if not hubs:
        return out
    hub = hubs[0]
    for color, cells in pts.items():
        if len(cells) < 2:
            continue
        a, b = cells[0], cells[1]
        dr, dc = b[0]-a[0], b[1]-a[1]
        if dr == 0 and dc == 0:
            continue
        # Continue in direction away from hub, past the farther pair endpoint.
        da = (a[0]-hub[0])**2 + (a[1]-hub[1])**2
        db = (b[0]-hub[0])**2 + (b[1]-hub[1])**2
        if da >= db:
            r, c = a
            sr, sc = -dr, -dc
        else:
            r, c = b
            sr, sc = dr, dc
        while 0 <= r+sr < h and 0 <= c+sc < w:
            r, c = r+sr, c+sc
            if out[r][c] == background:
                out[r][c] = color
    return out
